// ==========================================
// 1. GLOBAL PROJECT METADATA
// ==========================================
Project doku_store_core {
  database_type: 'PostgreSQL'
  Note: 'Core Architecture Database Specification for Dokudocs E-Commerce Platform'
}

// ==========================================
// 2. ENUM DEFINITIONS
// ==========================================
Enum user_role {
  customer
  merchant
  admin
  superadmin
}

Enum order_status {
  pending
  processing
  paid
  shipped
  delivered
  cancelled
}

Enum payment_gateway {
  doku_wallet
  credit_card
  virtual_account
  qris
}

// ==========================================
// 3. TABLE DEFINITIONS & FIELD CONSTRAINTS
// ==========================================

Table users as U {
  id uuid [pk, default: `gen_random_uuid()`]
  username varchar(50) [unique, not null]
  email varchar(255) [unique, not null]
  password_hash varchar(255) [not null]
  role user_role [default: 'customer', not null]
  is_active boolean [default: true]
  created_at timestamp [default: `now()`]
  updated_at timestamp [default: `now()`]

  Note: 'Master data credentials & account authentication'
}

Table profiles {
  id uuid [pk, default: `gen_random_uuid()`]
  user_id uuid [unique, not null, ref: - users.id]
  full_name varchar(150) [not null]
  phone_number varchar(20) [unique]
  avatar_url text
  bio text [note: 'User bio description up to 500 chars']
  birth_date date
  updated_at timestamp [default: `now()`]
}

Table merchants {
  id uuid [pk, default: `gen_random_uuid()`]
  owner_id uuid [not null, ref: > users.id]
  store_name varchar(100) [not null]
  store_slug varchar(100) [unique, not null]
  is_verified boolean [default: false]
  created_at timestamp [default: `now()`]
}

Table categories {
  id int [pk, increment]
  parent_id int [null, ref: > categories.id]
  name varchar(100) [not null]
  slug varchar(100) [unique, not null]
  description text
}

Table products {
  id uuid [pk, default: `gen_random_uuid()`]
  merchant_id uuid [not null, ref: > merchants.id]
  category_id int [not null, ref: > categories.id]
  name varchar(255) [not null]
  sku varchar(50) [unique, not null]
  price decimal(12,2) [not null, default: 0.00]
  stock int [not null, default: 0]
  is_published boolean [default: true]
  created_at timestamp [default: `now()`]

  indexes {
  (merchant_id, category_id) [name: 'idx_product_merchant_category']
  price [name: 'idx_product_price']
}
}

Table orders {
  id uuid [pk, default: `gen_random_uuid()`]
  order_number varchar(32) [unique, not null]
  user_id uuid [not null, ref: > users.id]
  merchant_id uuid [not null, ref: > merchants.id]
  status order_status [default: 'pending', not null]
  total_amount decimal(12,2) [not null]
  shipping_address text [not null]
  ordered_at timestamp [default: `now()`]

  indexes {
  (user_id, status)
  ordered_at
}
}

Table order_items {
  id bigint [pk, increment]
  order_id uuid [not null, ref: > orders.id]
  product_id uuid [not null, ref: > products.id]
  quantity int [not null, default: 1]
  unit_price decimal(12,2) [not null]
  subtotal decimal(12,2) [not null]
}

Table payments {
  id uuid [pk, default: `gen_random_uuid()`]
  order_id uuid [unique, not null, ref: - orders.id]
  gateway payment_gateway [not null]
  transaction_ref varchar(100) [unique, not null]
  amount decimal(12,2) [not null]
  paid_at timestamp
  created_at timestamp [default: `now()`]
}

Table audit_logs {
  id bigint [pk, increment]
  user_id uuid [null, ref: > users.id]
  action varchar(100) [not null]
  resource_type varchar(50) [not null]
  resource_id varchar(100) [not null]
  ip_address varchar(45)
  created_at timestamp [default: `now()`]
}

TableGroup Identity_And_Access {
  users
  profiles
  audit_logs
}

TableGroup Catalog_And_Store {
  merchants
  categories
  products
}

TableGroup Sales_And_Transactions {
  orders
  order_items
  payments
}
